contract SingleStreamConsumer is TokenStreamConsumer {
    event RewardSource(address source);

    ITokenStreamEmitter private immutable source;
    uint256 private immutable nToken;
    address private immutable token0;
    address private immutable token1;
    address[] private _tokens;

    constructor(ITokenStreamEmitter source_) {
        source = source_;
        emit RewardSource(address(source));
        address[] memory tokens = source.outputTokens();
