        token1 = nToken >= 2 ? tokens[1] : address(0);
        if (nToken >= 3) _tokens = tokens;
    }

    function _inputTokens() internal view virtual override returns (address[] memory) {
        if (nToken <= 2) {
            address[] memory ret = new address[](nToken);
            if (nToken >= 1) ret[0] = token0;
            if (nToken >= 2) ret[1] = token1;
            return ret;
        }
        return _tokens;
    }

    function _takeInputRaw(address token, address recipient, uint128 amountMax) internal virtual override returns (uint128) {
        return source.collect(token, recipient, amountMax);
    }

    function _pendingInputAmountUncached(address token) internal view virtual override returns (uint128) {
        return source.collectableAmount(token, address(this));
    }

    function _pendingInputAmountWithUpdateUncached(address token) internal override returns (uint128) {
        return source.collectableAmountWithUpdate(token, address(this));
    }

    function _tokenInputPerSecondX128(address token) internal view virtual override returns (uint256) {
        return source.tokenOutputPerSecondX128(token, address(this));
    }
}

