pragma solidity ^0.8.10;

import "openzeppelin-v5/utils/math/Math.sol";

library StakingMath {
    event StakeDisabled(address indexed account);
    event StakeEnabled(address indexed account);
    event Stake(address indexed account, uint128 amount);
    event Unstake(address indexed account, uint128 amount);
    event Distribute(address indexed rewardToken, uint256 amount);
    event Collect(address indexed rewardToken, address indexed account, uint256 amount);
    event Poke(address account, address rewardToken);

    struct StakeAccount {
        bool disabled;
        uint128 stakes;
    }

    struct Ledger {
        uint256 totalStakes;
        mapping(address => StakeAccount) accounts;
        mapping(address => Reward) rewards;
    }

    struct Reward {
        uint256 rewardGrowthX128;
        uint128 undistributed;
        mapping(address => Account) accounts;
    }

    struct Account {
        uint256 rewardGrowthLastX128;
        uint128 rewardsOwed;
    }

    using StakingMath for Ledger;

    function _calculateRewardGrowth(uint256 totalStakes, uint128 newRewardsAmount) internal pure returns (uint256) {
        if (totalStakes == 0) return 0;
        unchecked {
            return ((uint256(newRewardsAmount) << 128) / totalStakes);
        }
    }

    function disable(Ledger storage self, address account) internal {
        StakeAccount storage sa = self.accounts[account];
        if (!sa.disabled) {
            sa.disabled = true;
            self.totalStakes -= sa.stakes;
            emit StakeDisabled(account);
        }
    }

    function enable(Ledger storage self, address account) internal {
        StakeAccount storage sa = self.accounts[account];
        if (sa.disabled) {
            sa.disabled = false;
            self.totalStakes += sa.stakes;
            emit StakeEnabled(account);
        }
    }

    function effectiveStakes(Ledger storage self, address account) internal view returns (uint128) {
        StakeAccount storage sa = self.accounts[account];
        if (sa.disabled) return 0;
        return sa.stakes;
    }

    function _calculateRewardsOwed(uint128 userStakes, uint256 rewardGrowthX128, uint256 rewardGrowthLastX128) internal pure returns (uint128 rewardsOwed) {
        return uint128(Math.min(type(uint128).max, Math.mulDiv(userStakes, rewardGrowthX128 - rewardGrowthLastX128, 1 << 128)));
    }

    function balanceOf(Ledger storage self, address account) internal view returns (uint128) {
        StakeAccount storage sa = self.accounts[account];
        return sa.stakes;
    }

    function stake(Ledger storage self, address account, uint128 amount) internal {
        if (amount == 0) return;
        StakeAccount storage sa = self.accounts[account];
        sa.stakes += amount;
        if (!sa.disabled) self.totalStakes += amount;
        emit Stake(account, amount);
    }

    function unstake(Ledger storage self, address account, uint128 amount) internal {
        if (amount == 0) return;
        StakeAccount storage sa = self.accounts[account];
        sa.stakes -= amount;
        if (!sa.disabled) self.totalStakes -= amount;
        emit Unstake(account, amount);
    }

    function unstakeAll(Ledger storage self, address account) internal returns (uint128) {
        StakeAccount storage sa = self.accounts[account];
        uint128 amount = sa.stakes;
        self.unstake(account, amount);
        return amount;
    }

    function distribute(Ledger storage self, address rewardToken, uint128 amount) internal {
        if (amount == 0) return;
        Reward storage reward = self.rewards[rewardToken];
        if (self.totalStakes == 0) reward.undistributed += amount;
        else reward.rewardGrowthX128 += _calculateRewardGrowth(self.totalStakes, amount);
        emit Distribute(rewardToken, amount);
    }

    function poke(Ledger storage self, address rewardToken, address account) internal {
        Reward storage reward = self.rewards[rewardToken];
        Account storage acc = reward.accounts[account];
        acc.rewardsOwed = uint128(Math.min(type(uint128).max, uint256(acc.rewardsOwed) + _calculateRewardsOwed(self.effectiveStakes(account), reward.rewardGrowthX128, acc.rewardGrowthLastX128)));
        acc.rewardGrowthLastX128 = reward.rewardGrowthX128;
        emit Poke(account, rewardToken);
    }

    function poke(Ledger storage self, address[] memory rewardTokens, address account) internal {
        uint128 effectiveStake = self.effectiveStakes(account);
        for (uint256 i = 0; i < rewardTokens.length; i++) {
            address rewardToken = rewardTokens[i];
            Reward storage reward = self.rewards[rewardToken];
            Account storage acc = reward.accounts[account];
            acc.rewardsOwed = uint128(Math.min(type(uint128).max, uint256(acc.rewardsOwed) + _calculateRewardsOwed(effectiveStake, reward.rewardGrowthX128, acc.rewardGrowthLastX128)));
            acc.rewardGrowthLastX128 = reward.rewardGrowthX128;
            emit Poke(account, rewardToken);
        }
    }

    function owed(Ledger storage self, address rewardToken, address account) internal view returns (uint128) {
        Reward storage reward = self.rewards[rewardToken];
        Account storage acc = reward.accounts[account];

        return acc.rewardsOwed;
    }

    function claimable(Ledger storage self, address rewardToken, uint128 newRewards, address account) internal view returns (uint128) {
        Reward storage reward = self.rewards[rewardToken];
        Account storage acc = reward.accounts[account];
        uint256 rewardGrowthX128 = reward.rewardGrowthX128 + _calculateRewardGrowth(self.totalStakes, newRewards);

        return uint128(Math.min(type(uint128).max, uint256(acc.rewardsOwed) + _calculateRewardsOwed(self.effectiveStakes(account), rewardGrowthX128, acc.rewardGrowthLastX128)));
    }

    function collect(Ledger storage self, address rewardToken, address account, uint128 amountMax) internal returns (uint128 amount) {
        Reward storage reward = self.rewards[rewardToken];
        Account storage acc = reward.accounts[account];
        uint128 claimableAmount = uint128(Math.min(type(uint128).max, acc.rewardsOwed));
        amount = amountMax <= claimableAmount ? amountMax : claimableAmount;
        if (amount > 0) {
            acc.rewardsOwed -= amount;
            emit Collect(rewardToken, account, amount);
        }
    }

    function collectUndistributed(Ledger storage self, address rewardToken) internal returns (uint128 amount) {
        Reward storage reward = self.rewards[rewardToken];
        amount = reward.undistributed;
        reward.undistributed = 0;
    }
}

